import requests
from flask import Flask, request, redirect

app = Flask(__name__)

# Define a set of trusted domains
TRUSTED_DOMAINS = {'example.com', 'trustedsubdomain.com'}

@app.route("/full_ssrf")
def full_ssrf():
    '''
    Get the subdomain from the request and use it as the url, make a request to the url, and return the response
    '''
    # Get the host from the request
    host = request.host.split(':')[0]  # Extract the hostname without port

    # Check if the host is in the trusted domains list
    if host not in TRUSTED_DOMAINS:
        return "Access denied", 403

    # Make a request to the provided URL
    try:
        response = requests.get(f"http://{host}")
        return response.text, response.status_code
    except requests.RequestException as e:
        return str(e), 500

if __name__ == "__main__":
    app.run(debug=True)
